What is the security bug in this Server Action?

```ts
'use server'
export async function deletePost(postId: string) {
  const session = await auth()
  if (!session?.user) throw new Error('Unauthorized')
  await db.post.delete({ where: { id: postId } })
}
```

The admin page below redirects non-admins. A logged-in non-admin captures the action's request and replays it directly. What happens?

```tsx
export default async function AdminPage() {
  const session = await auth()
  if (!session?.user?.isAdmin) redirect('/login')
  return (
    <form action={async () => {
      'use server'
      await db.record.deleteMany()
    }}>
      <button>Delete records</button>
    </form>
  )
}
```

A Server Component passes a database row to a Client Component. The UI shows only the name. Which data ends up in what the browser receives?

```tsx
// app/u/[slug]/page.tsx (Server Component)
const [rows] = await sql`SELECT * FROM user WHERE slug = ${slug}`
return <Profile user={rows[0]} />

// app/u/profile.tsx
'use client'
export default function Profile({ user }) {
  return <h1>{user.name}</h1>
}
```

With Cache Components enabled, a team caches notes per user. Which version can leak another user's notes?

```ts
// lib/data.ts
export async function getNotesByUserId(userId: string) {
  'use cache'
  cacheTag(`notes:${userId}`)
  return db.query.notes.findMany({ where: eq(notes.userId, userId) })
}

// app/actions.ts
'use server'
export async function loadNotes(userId: string) {
  return getNotesByUserId(userId)
}
```

Two DAL helpers both avoid repeated session lookups. On a long-running Node.js server, which one can show user A's data to user B?

```ts
// Helper 1
export const getUser = cache(async () => {
  const token = (await cookies()).get('session')?.value
  return lookupUser(token)
})

// Helper 2
let current: User | null = null
export async function getUser2() {
  if (!current) {
    const token = (await cookies()).get('session')?.value
    current = await lookupUser(token)
  }
  return current
}
```
